// Synthetic Standard MIDI File fixtures.
//
// Every byte here is generated by this module. No commercial or user-supplied
// song file is checked into the repository, so a reviewer can read the note
// list above each fixture and re-derive the exact bytes the tests parse.
//
// The builders are deliberately dumb: they emit what they are told, including
// malformed framing, so a fail-closed path can be exercised with real bytes
// rather than with a mocked decoder.

export const vlq = value => {
  const out = [value & 0x7f];
  let rest = Math.floor(value / 128);
  while (rest > 0) {
    out.unshift(0x80 | (rest & 0x7f));
    rest = Math.floor(rest / 128);
  }
  return out;
};

export const be = (value, bytes) => Array.from({ length: bytes }, (_, i) => (value >> ((bytes - 1 - i) * 8)) & 0xff);
export const chunk = (type, body) => [...Array.from(type, c => c.charCodeAt(0)), ...be(body.length, 4), ...body];

// `entries` are [delta, ...bytes]. End of Track is appended unless the caller
// asks for a track without one.
export const buildTrack = (entries, { endOfTrack = true } = {}) => {
  const body = entries.flatMap(([delta, ...bytes]) => [...vlq(delta), ...bytes]);
  if (endOfTrack) body.push(...vlq(0), 0xff, 0x2f, 0x00);
  return chunk('MTrk', body);
};

export const buildMidi = ({ format = 1, division = 360, tracks, declaredTrackCount = null }) => new Uint8Array([
  ...chunk('MThd', [...be(format, 2), ...be(declaredTrackCount ?? tracks.length, 2), ...be(division, 2)]),
  ...tracks.flat(),
]);

export const meta = (type, data) => [0xff, type, data.length, ...data];
export const setTempo = us => meta(0x51, [(us >> 16) & 0xff, (us >> 8) & 0xff, us & 0xff]);
export const timeSig = (numerator, denominatorPowerOfTwo) => meta(0x58, [numerator, denominatorPowerOfTwo, 24, 8]);
export const trackName = name => meta(0x03, Array.from(name, c => c.charCodeAt(0)));
export const programChange = (channel, program) => [0xc0 | channel, program];
export const noteOn = (channel, pitch, velocity = 96) => [0x90 | channel, pitch, velocity];
export const noteOff = (channel, pitch, velocity = 0x40) => [0x80 | channel, pitch, velocity];

// Absolute-tick note list -> delta-encoded entries. A stable sort on
// (tick, release-before-attack, pitch) keeps the byte stream deterministic.
export const notesToEntries = (notes, { releaseAsVelocityZero = false } = {}) => {
  const events = [];
  for (const [channel, pitch, onTick, offTick, velocity = 96] of notes) {
    events.push({ tick: onTick, release: 0, pitch, bytes: noteOn(channel, pitch, velocity) });
    events.push({ tick: offTick, release: 1, pitch, bytes: releaseAsVelocityZero ? noteOn(channel, pitch, 0) : noteOff(channel, pitch) });
  }
  events.sort((a, b) => a.tick - b.tick || b.release - a.release || a.pitch - b.pitch);
  let last = 0;
  return events.map(event => {
    const delta = event.tick - last;
    last = event.tick;
    return [delta, ...event.bytes];
  });
};

// PPQ 360 divides exactly into thirds (120), twelfths (30) and twenty-fourths
// (15), so a fixture can carry genuine 1/3, 2/3, 1/12 and 5/24 beat positions
// that a float projection would smear.
export const PPQ = 360;

// ── named fixtures ──────────────────────────────────────────────────────────

// Format 0: one track carrying tempo, meter and a three-note phrase.
export const format0 = () => buildMidi({
  format: 0,
  division: PPQ,
  tracks: [buildTrack([
    [0, ...trackName('Single track')],
    [0, ...setTempo(500000)],
    [0, ...timeSig(4, 2)],
    ...notesToEntries([[0, 60, 0, PPQ], [0, 64, PPQ, PPQ * 2], [0, 67, PPQ * 2, PPQ * 3]]),
  ])],
});

// Format 1: a conductor track plus a melody track and a two-note accompaniment
// track, which is the shape most third-party files arrive in.
export const format1 = () => buildMidi({
  format: 1,
  division: PPQ,
  tracks: [
    buildTrack([[0, ...trackName('Conductor')], [0, ...setTempo(500000)], [0, ...timeSig(3, 2)]]),
    buildTrack([[0, ...trackName('Melody')], [0, ...programChange(0, 0)],
      ...notesToEntries([[0, 72, 0, PPQ], [0, 74, PPQ, PPQ * 2], [0, 76, PPQ * 2, PPQ * 3]])]),
    buildTrack([[0, ...trackName('Accompaniment')], [0, ...programChange(1, 48)],
      ...notesToEntries([[1, 48, 0, PPQ * 3], [1, 55, 0, PPQ * 3]])]),
  ],
});

// A legal SMF text meta event whose payload is whitespace. PR #20 fixed the
// defect where this destroyed an otherwise complete ingest.
export const blankTrackName = () => buildMidi({
  format: 1,
  division: PPQ,
  tracks: [
    buildTrack([[0, ...trackName('   ')], [0, ...setTempo(500000)],
      ...notesToEntries([[0, 60, 0, PPQ], [0, 62, PPQ, PPQ * 2]])]),
  ],
});

// Running status: the status byte appears once and the following events reuse
// it. Written by hand rather than through notesToEntries, which always emits a
// status byte.
export const runningStatus = () => buildMidi({
  format: 0,
  division: PPQ,
  tracks: [buildTrack([
    [0, ...setTempo(500000)],
    [0, 0x90, 60, 96],        // note-on, status present
    [PPQ, 60, 0],             // running status: note-on velocity 0 = release
    [0, 62, 96],              // running status: next attack
    [PPQ, 62, 0],             // running status: release
  ])],
});

// Every release encoded as note-on velocity 0.
export const velocityZeroReleases = () => buildMidi({
  format: 0,
  division: PPQ,
  tracks: [buildTrack([
    [0, ...setTempo(500000)],
    ...notesToEntries([[0, 60, 0, PPQ], [0, 64, PPQ, PPQ * 2]], { releaseAsVelocityZero: true }),
  ])],
});

// General MIDI channel 10 (index 9). These note numbers are drum-kit
// selectors, never pitches.
export const percussion = () => buildMidi({
  format: 1,
  division: PPQ,
  tracks: [
    buildTrack([[0, ...trackName('Pitched')], ...notesToEntries([[0, 60, 0, PPQ], [0, 64, PPQ, PPQ * 2]])]),
    buildTrack([[0, ...trackName('Drums')], ...notesToEntries([[9, 36, 0, PPQ / 2], [9, 38, PPQ, PPQ * 3 / 2], [9, 42, 0, PPQ / 4]])]),
  ],
});

// Same channel, same pitch, struck again before the first release. The decoder
// must keep both strikes and match releases FIFO.
export const overlappingSamePitch = () => buildMidi({
  format: 0,
  division: PPQ,
  tracks: [buildTrack([
    [0, ...setTempo(500000)],
    [0, ...noteOn(0, 60)],
    [PPQ / 2, ...noteOn(0, 60)],
    [PPQ / 2, ...noteOff(0, 60)],
    [PPQ, ...noteOff(0, 60)],
  ])],
});

// A program change after the first note-on. The earlier note must keep the
// program in force at its own attack.
export const programAtNoteOn = () => buildMidi({
  format: 0,
  division: PPQ,
  tracks: [buildTrack([
    [0, ...programChange(0, 0)],
    [0, ...noteOn(0, 60)],
    [PPQ, ...noteOff(0, 60)],
    [0, ...programChange(0, 73)],
    [0, ...noteOn(0, 64)],
    [PPQ, ...noteOff(0, 64)],
  ])],
});

// Onsets on exact thirds, twelfths and twenty-fourths of a beat.
export const rationalTiming = () => buildMidi({
  format: 0,
  division: PPQ,
  tracks: [buildTrack([
    [0, ...setTempo(500000)],
    ...notesToEntries([
      [0, 60, 0, PPQ / 3],                       // 0     -> 1/3
      [0, 62, PPQ / 3, PPQ * 2 / 3],             // 1/3   -> 2/3
      [0, 64, PPQ * 2 / 3, PPQ],                 // 2/3   -> 1
      [0, 65, PPQ, PPQ + PPQ / 12],              // 1     -> 13/12
      [0, 67, PPQ + PPQ / 12, PPQ + PPQ * 5 / 24], // 13/12 -> 29/24
      [0, 69, PPQ + PPQ * 5 / 24, PPQ * 2],      // 29/24 -> 2
    ]),
  ])],
});

// Six concurrent source voices: more independent material than the six-role
// arrangement target once Core3/Full6 competition is taken into account, so
// nothing may be dropped before G11-C reports it.
export const sixSourceVoices = () => buildMidi({
  format: 1,
  division: PPQ,
  tracks: [
    buildTrack([[0, ...setTempo(500000)], [0, ...timeSig(4, 2)]]),
    ...[[0, 84], [1, 76], [2, 72], [3, 64], [4, 55], [5, 43]].map(([channel, pitch], index) =>
      buildTrack([[0, ...trackName(`Voice ${index + 1}`)],
        ...notesToEntries([
          [channel, pitch, 0, PPQ * 2],
          [channel, pitch + 2, PPQ * 2, PPQ * 4],
          [channel, pitch, PPQ * 4, PPQ * 6],
        ])])),
  ],
});

// A track name is arbitrary attacker-controlled text: the SMF spec defines no
// encoding for it and a file can carry anything. It reaches the page, so markup
// in it is a real case, not a hypothetical one.
export const hostileTrackName = () => buildMidi({
  format: 0,
  division: PPQ,
  tracks: [buildTrack([
    [0, ...trackName('<script>alert("x")</script> & "quoted" \'name\'')],
    [0, ...setTempo(500000)],
    ...notesToEntries([[0, 60, 0, PPQ]]),
  ])],
});

// ── malformed / fail-closed fixtures ────────────────────────────────────────

export const notMidiAtAll = () => new Uint8Array(Array.from('this file is plain text, not a Standard MIDI File', c => c.charCodeAt(0)));

export const truncatedHeader = () => format0().subarray(0, 10);

// A complete header with a declared track length that runs past the file.
export const truncatedTrack = () => {
  const full = format0();
  return full.subarray(0, full.length - 12);
};

export const badChunkType = () => buildMidi({
  format: 0,
  division: PPQ,
  tracks: [chunk('XYZW', [0, 1, 2, 3]), buildTrack([...notesToEntries([[0, 60, 0, PPQ]])])],
});

// A track whose first event is a data byte with no status to inherit.
export const runningStatusWithoutStatus = () => buildMidi({
  format: 0,
  division: PPQ,
  tracks: [buildTrack([[0, 60, 96], [PPQ, 0x80, 60, 0x40]])],
});

// SMPTE division measures absolute time, so no musical beat can be derived.
export const smpteDivision = () => buildMidi({
  format: 0,
  division: 0xe728,
  tracks: [buildTrack([...notesToEntries([[0, 60, 0, 100]])])],
});

export const format2 = () => buildMidi({
  format: 2,
  division: PPQ,
  tracks: [buildTrack([...notesToEntries([[0, 60, 0, PPQ]])])],
});

// Data after End of Track inside one MTrk body.
export const dataAfterEndOfTrack = () => {
  const body = [...vlq(0), ...noteOn(0, 60), ...vlq(PPQ), ...noteOff(0, 60), ...vlq(0), 0xff, 0x2f, 0x00, ...vlq(0), ...noteOn(0, 72)];
  return buildMidi({ format: 0, division: PPQ, tracks: [chunk('MTrk', body)] });
};
